import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Typography, Button, Paper, useTheme, useMediaQuery } from '@mui/material';
import { Add as AddIcon } from '@mui/icons-material';
import AdminLayout from '../../../components/Layout/AdminLayout';
import AdminAppointmentList from '../../../components/AdminAppointmentList/AdminAppointmentList';
import { useQuery } from '@apollo/client';
import { GET_ALL_APPOINTMENTS } from '../../../graphql/admin';

const Appointments = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const { loading, error, data, refetch } = useQuery(GET_ALL_APPOINTMENTS, {
    fetchPolicy: 'network-only', // Always fetch fresh data
    onError: (error) => {
      console.error('Error loading appointments:', error);
    }
  });

  const handleNewAppointment = () => {
    navigate('/admin/appointments/new');
  };

  return (
    <AdminLayout>
      <Box 
        sx={{ 
          width: '100%',
          boxSizing: 'border-box',
          flexGrow: 1,
          display: 'flex',
          flexDirection: 'column',
          pl: { xs: 2, sm: 3 },
          pr: { xs: 2, sm: 3 },
          pt: 2
        }}
      >
        {/* Breadcrumbs */}
        <Breadcrumbs aria-label="breadcrumb" sx={{ mb: 2, ml: 0 }}>
          <MuiLink component={Link} to="/" color="inherit" sx={{ display: 'flex', alignItems: 'center' }}>
            <HomeIcon sx={{ mr: 0.5 }} fontSize="inherit" />
            Home
          </MuiLink>
          <MuiLink component={Link} to="/admin" color="inherit">
            Admin
          </MuiLink>
          <MuiLink component={Link} to="/admin/appointments" color="text.primary">
            Appointments
          </MuiLink>
          <Typography color="text.primary">All Appointments</Typography>
        </Breadcrumbs>

        <Box 
          sx={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            width: '100%',
            mb: 2
          }}
        >
          <Typography variant="h4" component="h1" sx={{ fontWeight: 500, color: 'text.primary' }}>
            All Appointments
          </Typography>
          <Box sx={{ [theme.breakpoints.down('sm')]: { width: '100%' } }}>
            <Button
              variant="contained"
              color="primary"
              startIcon={<AddIcon />}
              onClick={handleNewAppointment}
              size={isMobile ? 'medium' : 'medium'}
              sx={{
                minWidth: 180,
                [theme.breakpoints.down('sm')]: {
                  width: '100%',
                  maxWidth: 'none',
                  mt: 1
                }
              }}
            >
              New Appointment
            </Button>
          </Box>
        </Box>

        <Box sx={{ 
          p: isMobile ? 2 : 3, 
          pt: 2,
          flex: 1,
          display: 'flex',
          flexDirection: 'column'
        }}>
          <Paper 
            elevation={0}
            sx={{ 
              p: { xs: 2, sm: 3 },
              flex: 1,
              display: 'flex',
              flexDirection: 'column',
              backgroundColor: 'background.paper',
              borderRadius: 2,
              width: '100%',
              overflow: 'hidden'
            }}
          >
            <AdminAppointmentList 
              appointments={data?.allAppointments || []}
              loading={loading}
              error={error}
              onRefresh={() => refetch()}
            />
          </Paper>
        </Box>
      </Box>
    </AdminLayout>
  );
};

export default Appointments;
